cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ' columns:', cols.map(c => c.name).join(', '));
  const sample = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 2').all();
  console.log('Sample:', JSON.stringify(sample, null, 2));
}
"

cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Order details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Warranties for this order
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-E0E671'\").all();
console.log('\n=== WARRANTIES ===');
console.log(JSON.stringify(warranties, null, 2));

// Product details for items in order
const productIds = [...new Set(items.map(i => i.product_id))];
for (const pid of productIds) {
  const prod = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  console.log('\n=== PRODUCT: ' + pid + ' ===');
  console.log(JSON.stringify(prod, null, 2));
}

// Customer details
const customer = db.prepare(\"SELECT * FROM users WHERE user_id = ?\").get(order.customer_id);
console.log('\n=== CUSTOMER ===');
console.log(JSON.stringify(customer, null, 2));
"

