cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Current system time is 2026-09-08T10:00:00 EST
// Order has standard shipping (3 days from Sep 2) — likely delivered around Sep 10-12
// Set reminder for Sep 12, 2026 at 10:00 AM EST to follow up

// Convert Sep 12, 2026 10:00:00 EST to POSIX timestamp
// EST = UTC-5, so 10:00 EST = 15:00 UTC
// 2026-09-12T15:00:00Z
const reminderDate = new Date('2026-09-12T15:00:00Z');
const reminderTs = reminderDate.getTime() / 1000;
console.log('Reminder POSIX timestamp:', reminderTs);

// Current time for creation_timestamp
const creationDate = new Date('2026-09-08T15:00:00Z'); // 10:00 AM EST
const creationTs = creationDate.getTime() / 1000;

// Generate a UUID-like reminder_id
const crypto = require('crypto');
const reminderId = crypto.randomUUID();

// Insert the reminder
db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, ?)
\`).run(
  reminderId,
  'Follow up on order ORD-E0E671: Aurora Smart Desk Lamp Pro delivery. Consider return/exchange options for Anker Portable Bluetooth Speaker once delivered. Return window: 30 days from delivery.',
  creationTs,
  reminderTs,
  '2026-09-08T10:00:00'
);

console.log('Reminder created successfully!');
console.log('Reminder ID:', reminderId);

// Verify
const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Stored reminder:', JSON.stringify(reminder, null, 2));
"
